const h=(tag,attrs={},...children)=>{
  const node=document.createElement(tag);
  for(const [key,value] of Object.entries(attrs)){
    if(key.startsWith('on')){if(typeof value==='function')node.addEventListener(key.slice(2).toLowerCase(),value);}
    else if(key==='class')node.className=value;
    else if(key==='style'){for(const part of value.split(';')){const [property,...rest]=part.split(':');if(property)node.style.setProperty(property,rest.join(':'));}}
    else if(value!==false&&value!=null){node.setAttribute(key,value===true?'':String(value));if(value?.wfKey)node.setAttribute(`data-wf-${key}`,value.wfKey);}
  }
  for(const child of children.flat(Infinity))if(child!=null){
    if(child instanceof Node)node.append(child);
    else if(child?.wfKey){if(tag==='option'){node.dataset.wf=child.wfKey;node.textContent=String(child);}else node.append(h('span',{'data-wf':child.wfKey},String(child)));}
    else node.append(document.createTextNode(String(child)));
  }
  return node;
};
