  target.replaceChildren(h('div',{class:`wf-editor-grid${s.selected?' has-selection':''}`},s.library,middle,s.inspector));
  s.drawerEl=h('section',{class:'wf-run-drawer'});target.append(s.drawerEl);drawLibrary();drawCanvas();drawInspector();drawRunDrawer();if(!s.initialFit){fitCanvas();s.initialFit=true;}
